mapper.select:
SELECT
    l.id,
    l.biz_id AS bizId,
    l.module,
    l.action_type AS actionType,
    l.user_id AS userId,
    u.real_name AS userName,
    l.request_url AS requestUrl,
    l.request_method AS requestMethod,
    l.status,
    l.error_msg AS errorMsg,
    l.cost_time AS costTime,
    DATE_FORMAT(l.create_time, '%Y-%m-%d %H:%i:%s') AS createTime
FROM sys_log l
LEFT JOIN sys_user u ON l.user_id = u.id


        AND l.biz_id = #{query.bizId}


        AND l.module = #{query.module}


        AND l.action_type = #{query.actionType}


        AND l.user_id = #{query.userId}


        AND l.status = #{query.status}


        AND l.create_time >= #{query.startTime}


        AND l.create_time <= #{query.endTime}


ORDER BY l.create_time DESC, l.id DESC
